;; ---- frames and apps

(defmacro with-frame
  "Runs body with a fresh frame arena. Use around CUI calls made outside
  cui.core/run (setup code, or your own cui_begin_frame/cui_end_frame loop);
  keep the arena alive until the frame has been rendered."
  [& body]
  `(impl/call-with-arena (fn [] ~@body)))

(defn current-app
  "The cui_app* of the running cui.core/run loop."
  []
  impl/*app*)

(defn quit!
  "Asks the running app (or app) to close after this frame."
  ([] (quit! impl/*app*))
  ([app] (raw/cui_app_quit app)))

(defn run
  "Opens a window and calls (frame ui) once per frame until it closes.

  desc is a cui_app_desc map: {:title :width :height :min-width :min-height
  :fixed-size :continuous :no-vsync :hidden :renderer :theme :accent
  :follow-system-theme}. The loop is event driven: when nothing animates and
  no input arrives, it sleeps.

  Each frame's allocations live in an arena that is released only after the
  next frame has been presented, so pointers CUI keeps until it paints stay
  valid."
  [desc frame]
  (let [app (impl/call-with-arena #(app-create desc))]
    (when (or (nil? app) (zero? app))
      (throw (ex-info "cui: cui_app_create failed (no display?)" {:desc desc})))
    (try
      (loop [prev nil]
        (if (raw/cui_app_frame app)
          (let [a (ffi/confined-arena)]
            (try
              (binding [impl/*arena* a impl/*app* app]
                (frame (raw/cui_app_ui app)))
              (finally
                (when prev (ffi/close-arena prev))))
            (recur a))
          (when prev (ffi/close-arena prev))))
      (finally (raw/cui_app_destroy app)))))

(defmacro with-app
  "(with-app [ui {:title \"Hi\"}] body...) is (run desc (fn [ui] body...))."
  [[ui desc] & body]
  `(run ~desc (fn [~ui] ~@body)))

(defn screenshot
  "Renders the current UI into an RGBA byte-array. With only the app, the size
  is the window's own pixel size; returns [bytes width height]."
  ([app]
   (let [{:keys [x y]} (app-size app)
         s (raw/cui_dpi_scale (raw/cui_app_ui app))
         w (long (Math/round (* x s)))
         h (long (Math/round (* y s)))]
     [(screenshot app w h) w h]))
  ([app width height]
   (let [n (* 4 width height)
         p (ffi/alloc n)]
     (try
       (when-not (raw/cui_app_screenshot app p width height)
         (throw (ex-info "cui: screenshot buffer too small" {:width width :height height})))
       (ffi/read-array p n)
       (finally (ffi/free p))))))

(defn log-buffer
  "A log buffer for (log-view ui id buf): room for `lines` lines and
  `text-bytes` bytes of text, kept for the life of the process."
  ([] (log-buffer 2048 (* 256 1024)))
  ([lines text-bytes]
   (let [a (ffi/global-arena)
         buf (ffi/alloc a (:layout (impl/structs :cui_log_buffer)))
         ls (ffi/alloc a (* lines (:size (impl/structs :cui_log_line))))
         tx (ffi/alloc a text-bytes)]
     (raw/cui_log_init buf ls lines tx text-bytes)
     buf)))

(defn log!
  "Appends a line to a log-buffer: (log! buf :info \"Loaded %d rows\" n)."
  [buf level fmt & args]
  (let [s (apply format fmt args)]
    (raw/cui_log_append_text buf (impl/enum-val :cui_log_level level) (ffi/read buf :double) s -1)))
